mapper.select:
SELECT a.id, a.account_no, a.user_id, u.username, u.real_name, a.account_type, a.balance, a.status, a.currency, a.open_date, a.create_time FROM account a LEFT JOIN sys_user u ON a.user_id = u.id AND u.deleted = 0 WHERE a.deleted = 0
AND a.user_id = #{userId}
ORDER BY a.create_time DESC
